#!/bin/bash
#SBATCH --job-name=ALS_important_QTL_plots
#SBATCH --output=/home/zw529/donglab/data/target_ALS/QTL/important_QTL_plots_%j.out
#SBATCH --error=/home/zw529/donglab/data/target_ALS/QTL/important_QTL_plots_%j.err
#SBATCH --partition=week
#SBATCH --time=5-23:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=80G

# Standalone plotting-only job; run after generate_important_SNP_table.sh.
# All plotting helpers are compressed below and unpacked automatically at runtime.
# Evidence tables, priorities and scores are read only.
set -euo pipefail
# Clear inherited Conda/user/module Python paths, then build one module environment.
module purge
unset PYTHONPATH PYTHONHOME
export PYTHONNOUSERSITE=1
module load deepTools
export IMPORTANT_PYTHON="$(command -v python)"
command -v samtools >/dev/null
"$IMPORTANT_PYTHON" -u -c 'import sys,numpy,pandas,matplotlib,pyBigWig,scipy; print("Plot Python:",sys.executable); print("Matplotlib:",matplotlib.__file__)'
# Load R separately: its modules must not alter the Python plotting environment.
bash -lc 'module purge >/dev/null 2>&1; unset PYTHONPATH PYTHONHOME; module load R && Rscript -e '"'"'stopifnot(requireNamespace("ggplot2",quietly=TRUE),requireNamespace("gridExtra",quietly=TRUE),requireNamespace("data.table",quietly=TRUE))'"'"''
"$IMPORTANT_PYTHON" -u - "$@" <<'PLOTTING_ONLY_PYTHON'
import base64, json, lzma, subprocess, sys, tempfile
from pathlib import Path
